def strip_log_suffix(filename):
    # turn 'app.log' into 'app'
    return filename.strip(".log")


def archive_name(filename, date):
    return strip_log_suffix(filename) + "-" + date + ".gz"

from cleanup import strip_log_suffix, archive_name


def test_app_log():
    assert strip_log_suffix("app.log") == "app"


def test_glob_log():
    assert strip_log_suffix("glob.log") == "glob"


def test_login_log():
    assert strip_log_suffix("login.log") == "login"


def test_ollog_log():
    assert strip_log_suffix("ollog.log") == "ollog"


def test_no_suffix():
    assert strip_log_suffix("readme") == "readme"


def test_double_suffix_removed_once():
    assert strip_log_suffix("a.log.log") == "a.log"


def test_archive_name():
    assert archive_name("glob.log", "2026-01-05") == "glob-2026-01-05.gz"

